import{_ as a,o as e,c as r,a2 as d}from"./chunks/framework.C4u7U0Dw.js";const c=JSON.parse('{"title":"第 22 章 行业路线图：从通用能力到行业工作流","description":"","frontmatter":{},"headers":[],"relativePath":"bluebook/第四篇 岗位与行业落地/第 22 章 行业路线图：从通用能力到行业工作流.md","filePath":"bluebook/第四篇 岗位与行业落地/第 22 章 行业路线图：从通用能力到行业工作流.md"}'),o={name:"bluebook/第四篇 岗位与行业落地/第 22 章 行业路线图：从通用能力到行业工作流.md"};function s(n,t,l,i,h,p){return e(),r("div",null,[...t[0]||(t[0]=[d(`<h1 id="第-22-章-行业路线图-从通用能力到行业工作流" tabindex="-1">第 22 章 行业路线图：从通用能力到行业工作流 <a class="header-anchor" href="#第-22-章-行业路线图-从通用能力到行业工作流" aria-label="Permalink to &quot;第 22 章 行业路线图：从通用能力到行业工作流&quot;">​</a></h1><h2 id="_22-1-为什么分行业" tabindex="-1">22.1 为什么分行业 <a class="header-anchor" href="#_22-1-为什么分行业" aria-label="Permalink to &quot;22.1 为什么分行业&quot;">​</a></h2><p>岗位路线解决&quot;个人效率&quot;，行业路线解决&quot;业务落地&quot;。同一套通用能力，在医疗、金融、教育、内容行业里，会长成完全不同的工作流。</p><h2 id="_22-2-行业化方法论-三步走" tabindex="-1">22.2 行业化方法论：三步走 <a class="header-anchor" href="#_22-2-行业化方法论-三步走" aria-label="Permalink to &quot;22.2 行业化方法论：三步走&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第 1 步：识别行业核心任务流</span></span>
<span class="line"><span>第 2 步：为每个环节设计 AI 工作流</span></span>
<span class="line"><span>第 3 步：沉淀为行业模板，团队共享复用</span></span></code></pre></div><h2 id="_22-3-示例-内容-媒体行业" tabindex="-1">22.3 示例：内容/媒体行业 <a class="header-anchor" href="#_22-3-示例-内容-媒体行业" aria-label="Permalink to &quot;22.3 示例：内容/媒体行业&quot;">​</a></h2><p><strong>核心任务流：</strong> 选题 → 资料收集 → 写作 → 编辑 → 发布 → 数据复盘。</p><table tabindex="0"><thead><tr><th>环节</th><th>AI 工作流</th></tr></thead><tbody><tr><td>选题</td><td>资讯收集（第 14 章）+ 热点筛选</td></tr><tr><td>资料收集</td><td>素材整理 + 摘要（第 13 章）</td></tr><tr><td>写作</td><td>大纲先行 + 分块写作（第 9 章）</td></tr><tr><td>编辑</td><td>风格检查、事实核对清单</td></tr><tr><td>数据复盘</td><td>数据清洗 + 结论（第 12 章）</td></tr></tbody></table><p><strong>沉淀：</strong> 选题 Skill、写作模板 Skill、复盘报告 Skill。</p><h2 id="_22-4-示例-教育培训行业" tabindex="-1">22.4 示例：教育培训行业 <a class="header-anchor" href="#_22-4-示例-教育培训行业" aria-label="Permalink to &quot;22.4 示例：教育培训行业&quot;">​</a></h2><p><strong>核心任务流：</strong> 课程设计 → 内容制作 → 学员支持 → 效果评估。</p><table tabindex="0"><thead><tr><th>环节</th><th>AI 工作流</th></tr></thead><tbody><tr><td>课程设计</td><td>大纲生成 + 教学目标拆解</td></tr><tr><td>内容制作</td><td>讲义/PPT 结构 + 习题生成</td></tr><tr><td>学员支持</td><td>FAQ 整理、答疑话术</td></tr><tr><td>效果评估</td><td>成绩分析 + 薄弱点识别（第 12 章）</td></tr></tbody></table><p><strong>沉淀：</strong> 课件模板 Skill、习题生成 Skill、学情分析流程。</p><h2 id="_22-5-示例-电商零售行业" tabindex="-1">22.5 示例：电商零售行业 <a class="header-anchor" href="#_22-5-示例-电商零售行业" aria-label="Permalink to &quot;22.5 示例：电商零售行业&quot;">​</a></h2><p><strong>核心任务流：</strong> 选品 → 上架 → 营销 → 客服 → 复盘。</p><table tabindex="0"><thead><tr><th>环节</th><th>AI 工作流</th></tr></thead><tbody><tr><td>选品</td><td>市场数据汇总 + 趋势判断</td></tr><tr><td>上架</td><td>商品文案生成 + 信息核对</td></tr><tr><td>营销</td><td>活动方案 + 多版本文案（第 9 章）</td></tr><tr><td>客服</td><td>话术库整理 + 常见问题分类</td></tr><tr><td>复盘</td><td>销售数据清洗 + 渠道分析（第 12 章）</td></tr></tbody></table><p><strong>沉淀：</strong> 文案模板 Skill、数据复盘流程、自动化日报（第 15 章）。</p><h2 id="_22-6-行业落地的保障" tabindex="-1">22.6 行业落地的保障 <a class="header-anchor" href="#_22-6-行业落地的保障" aria-label="Permalink to &quot;22.6 行业落地的保障&quot;">​</a></h2><ol><li><strong>合规先行</strong>：涉及医疗/金融/隐私数据，先确认数据授权与合规边界；</li><li><strong>人工终审</strong>：行业内容（医疗建议、金融决策）永远由专业人士终审；</li><li><strong>口径沉淀</strong>：行业术语、业务口径写进记忆（第 20 章），避免每次重讲；</li><li><strong>小步试点</strong>：先选 1 个环节试点，跑通再铺开，不要一次全行业化。</li></ol><h2 id="_22-7-从行业到组织-组建-ai-团队" tabindex="-1">22.7 从行业到组织：组建 AI 团队 <a class="header-anchor" href="#_22-7-从行业到组织-组建-ai-团队" aria-label="Permalink to &quot;22.7 从行业到组织：组建 AI 团队&quot;">​</a></h2><p>行业工作流跑通后，下一步是<strong>组织化</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>单人流程 → 团队共享（第 17 章 Skill 共享）</span></span>
<span class="line"><span>→ 多角色系统（第 18 章）→ 自动化保障（第 19 章）</span></span>
<span class="line"><span>→ 团队长期上下文（第 20 章）</span></span></code></pre></div><p>此时你拥有的不是&quot;几个 AI 技巧&quot;，而是一套<strong>属于你行业和组织的 AI 生产力系统</strong>。</p><h2 id="_22-8-练习" tabindex="-1">22.8 练习 <a class="header-anchor" href="#_22-8-练习" aria-label="Permalink to &quot;22.8 练习&quot;">​</a></h2><ol><li>画出你所在行业的&quot;核心任务流&quot;（5～8 个环节）；</li><li>标出其中 3 个环节可 AI 化的点；</li><li>选 1 个环节，设计它的 AI 工作流并试点跑通。</li></ol><blockquote><p>结语：白皮书到这里结束，但你的行业化才刚刚开始。从第一张任务流开始，把通用能力落成行业资产——这就是&quot;从一项任务到一支 AI 团队&quot;的最终形态。</p></blockquote>`,26)])])}const b=a(o,[["render",s]]);export{c as __pageData,b as default};
